<script>
	import axios from 'axios';
	import AddOrUpdate from "./add-or-update";
	import luyongxinxiCrossAddOrUpdate from "../luyongxinxi/add-or-update";
	import {
		Loading
	} from 'element-ui';
	export default {
		data() {
			return {
				indexQueryCondition: '',
				mianshijieguoOptions: [],
        shifoucanchuOptions: [],  // 添加选项
        mianshixingshiOptions: [],  // 添加选项
				searchForm: {
					key: ""
				},
				form:{},
				dataList: [],
				pageIndex: 1,
				pageSize: 10,
				totalPage: 0,
				dataListLoading: false,
				dataListSelections: [],
				showFlag: true,
				addOrUpdateFlag:false,
				luyongxinxiCrossAddOrUpdateFlag: false,
				layouts: ["prev","pager","next","sizes"],
				previewImg: '',
				previewVisible: false,
			};
		},
		created() {
			this.init();
			this.getDataList();
			this.contentStyleChange();
		},
		mounted() {
		},
		filters: {
			htmlfilter: function (val) {
				return val.replace(/<[^>]*>/g).replace(/undefined/g,'');
			}
		},
		computed: {
			tablename(){
				return this.$storage.get('sessionTable')
			},
		},
		components: {
			AddOrUpdate,
			luyongxinxiCrossAddOrUpdate,
		},
		methods: {
      handleLuYong(row) {
        console.log('点击录用通知, 当前行数据:', row);
        
        // 判断是否参加面试
        console.log('检查是否确认参加:', row.shifoucanchu);
        if (row.shifoucanchu !== '是') {
          this.$message({
            message: '求职者未确认参加面试，无法发送录用通知',
            type: "warning",
            duration: 1500
          });
          return;
        }

        // 检查该求职者是否已被录用（一个人只能被录用一次）
        console.log('查询录用记录:', {
          qiuzhizhanghao: row.qiuzhizhanghao
        });
        this.$http({
          url: "luyongxinxi/page",
          method: "get",
          params: {
            qiuzhizhanghao: row.qiuzhizhanghao,
            page: 1,
            limit: 100
          }
        }).then(({ data }) => {
          console.log('录用记录查询结果:', data);
          if (data && data.code === 0 && data.data.total > 0) {
            // 判断是否被当前企业录用
            const currentQiye = this.$storage.get('adminName');
            const luyongRecord = data.data.list[0];
            const luyongQiye = luyongRecord.qiyemingcheng;
            
            if (luyongQiye === currentQiye) {
              // 本企业已录用（任何岗位），跳转到录用信息列表查看详情
              this.$message({
                message: '该求职者已被您录用',
                type: "warning",
                duration: 1500
              });
              this.$router.push({path: 'luyongxinxi'});
              return;
            } else {
              // 被其他企业录用
              this.$message({
                message: '该求职者已被其他企业录用，不能重复录用',
                type: "error",
                duration: 1500
              });
              return;
            }
          }
          
          // 如果未被录用，则执行录用通知逻辑
          console.log('执行录用通知逻辑');
          this.luyongxinxiCrossAddOrUpdateHandler(row, 'cross', '', '', 'mianshijieguo', '已录用', '已录用,未录用'.split(',')[0]);
        });
      },
			imgPreView(url){
				this.previewImg = url
				this.previewVisible = true
			},
			contentStyleChange() {
				this.contentPageStyleChange()
			},
			// 分页
			contentPageStyleChange(){
				let arr = []

				// if(this.contents.pageTotal) arr.push('total')
				// if(this.contents.pageSizes) arr.push('sizes')
				// if(this.contents.pagePrevNext){
				//   arr.push('prev')
				//   if(this.contents.pagePager) arr.push('pager')
				//   arr.push('next')
				// }
				// if(this.contents.pageJumper) arr.push('jumper')
				// this.layouts = arr.join()
				// this.contents.pageEachNum = 10
			},
			luyongxinxiCrossAddOrUpdateHandler(row,type,crossOptAudit,crossOptPay,statusColumnName,tips,statusColumnValue){
				this.showFlag = false;
				this.addOrUpdateFlag = false;
				this.luyongxinxiCrossAddOrUpdateFlag = true;
				this.$storage.set('crossObj',row);
				this.$storage.set('crossTable','mianshixinxi');
				this.$storage.set('statusColumnName',statusColumnName);
				this.$storage.set('statusColumnValue',statusColumnValue);
				this.$storage.set('tips',tips);
				if(statusColumnName!=''&&!statusColumnName.startsWith("[")) {
					var obj = this.$storage.getObj('crossObj');
					for (var o in obj){
						if(o==statusColumnName && obj[o]==statusColumnValue){
							this.$message({
								message: tips,
								type: "success",
								duration: 1500,
								onClose: () => {
									this.getDataList();
								}
							});
							this.showFlag = true;
							this.luyongxinxiCrossAddOrUpdateFlag = false;
							return;
						}
					}
				}
				this.$nextTick(() => {
					this.$refs.luyongxinxiCrossaddOrUpdate.init(row.id,type);
				});
			},





      init () {
        this.mianshijieguoOptions = "已录用,未录用".split(',')
        this.shifoucanchuOptions = "是,否".split(',')  // 修改为只能选择是或否
        this.mianshixingshiOptions = "线下面试,线上面试,电话面试".split(',')  // 添加初始化
      },
      search() {
        this.pageIndex = 1;
        this.getDataList();
      },

// 获取数据列表
      getDataList() {
        this.dataListLoading = true;
        let params = {
          page: this.pageIndex,
          limit: this.pageSize,
          sort: 'id',
          order: 'desc',
        }
        if(this.searchForm.qiyemingcheng!='' && this.searchForm.qiyemingcheng!=undefined){
          params['qiyemingcheng'] = '%' + this.searchForm.qiyemingcheng + '%'
        }
        if(this.searchForm.mianshijieguo!='' && this.searchForm.mianshijieguo!=undefined){
          params['mianshijieguo'] = this.searchForm.mianshijieguo
        }
        // 添加新字段搜索条件
        if(this.searchForm.shifoucanchu!='' && this.searchForm.shifoucanchu!=undefined){
          params['shifoucanchu'] = this.searchForm.shifoucanchu
        }
        if(this.searchForm.mianshixingshi!='' && this.searchForm.mianshixingshi!=undefined){
          params['mianshixingshi'] = this.searchForm.mianshixingshi
        }
        let user = JSON.parse(this.$storage.getObj('userForm'))
        this.$http({
          url: "mianshixinxi/page",
          method: "get",
          params: params
        }).then(({ data }) => {
          if (data && data.code === 0) {
            this.dataList = data.data.list;
            this.totalPage = data.data.total;
          } else {
            this.dataList = [];
            this.totalPage = 0;
          }
          this.dataListLoading = false;
        });
      },

      // 每页数
			sizeChangeHandle(val) {
				this.pageSize = val;
				this.pageIndex = 1;
				this.getDataList();
			},
			// 当前页
			currentChangeHandle(val) {
				this.pageIndex = val;
				this.getDataList();
			},
			// 多选
			selectionChangeHandler(val) {
				this.dataListSelections = val;
			},
			// 添加/修改
			addOrUpdateHandler(id,type) {
				this.showFlag = false;
				this.addOrUpdateFlag = true;
				this.crossAddOrUpdateFlag = false;
				if(type!='info'&&type!='msg'){
					type = 'else';
				}
				this.$nextTick(() => {
					this.$refs.addOrUpdate.init(id,type);
				});
			},
			// 删除
			async deleteHandler(id ) {
				var ids = id? [Number(id)]: this.dataListSelections.map(item => {
					return Number(item.id);
				});
				await this.$confirm(`确定进行[${id ? "删除" : "批量删除"}]操作?`, "提示", {
					confirmButtonText: "确定",
					cancelButtonText: "取消",
					type: "warning"
				}).then(async () => {
					await this.$http({
						url: "mianshixinxi/delete",
						method: "post",
						data: ids
					}).then(async ({ data }) => {
						if (data && data.code === 0) {
							this.$message({
								message: "操作成功",
								type: "success",
								duration: 1500,
								onClose: () => {
									this.search();
								}
							});
			
						} else {
							this.$message.error(data.msg);
						}
					});
				});
			},


		}

	};
</script>
